@Override
public CacheEntry set(CacheKey cacheKey,
                      CacheEntry entry) {
    lock.lock();
    try {
        entry = putIntoStore(cacheKey, entry);
        EvictionPolicy policy = getEvictionPolicy();
        policy.touch(cacheKey);
        CacheKey evictedKey = policy.evictNext();

        if (evictedKey != null) {
            delete(evictedKey);
            stats.evict();
        }

        for (Object redisKey : cacheKey.getRedisKeys()) {
            ByteBuffer mapKey = makeKeyForRedisKeysToCacheKeys(redisKey);

            if (redisKeysToCacheKeys.containsKey(mapKey)) {
                redisKeysToCacheKeys.get(mapKey).add(cacheKey);
            } else {
                Set<CacheKey<?>> set = ConcurrentHashMap.newKeySet();
                set.add(cacheKey);
                redisKeysToCacheKeys.put(mapKey, set);
            }
        }

        stats.load();
        return entry;
    } finally {
        lock.unlock();
    }
}

@ SuppressWarnings("unchecked" ) void remove(PublishSubscription<T> ps) {
    for(;;) {
        PublishSubscription<T>[] a = subscribers.get();
        if (a == TERMINATED || a == EMPTY) {
            return;
        }

        int n = a.length;
        int j = -1;
        for(int i = 0; i < n; i++) {
            if (a[i] == ps) {
                j = i;
                break;
            }
        }
        if (j < 0) {
            return;
        }
        PublishSubscription<T>[] b;
        if (n == 1) {
            b = EMPTY;
        } else {
            b = new PublishSubscription[n - 1];
            System.arraycopy(a, 0, b, 0, j);
            System.arraycopy(a, j+1, b, j, n - j - 1);
        }
        if (subscribers.compareAndSet(a, b)) {
            return;
        }
    }
}

